('lib/content/gpx_scolarite/dps_dpg/procédure_pénale_pages/pp_mandats_types.dart','f00021','2.1.2.1 — Agents habilités',21,'TextSpan','Le mandat de recherche est notifié et exécuté par un officier ou un agent de police judiciaire ou un agent de la force publique, qui en fait exhibition à la personne et lui en délivre copie (','Le mandat de recherche est notifié et exécuté par un officier ou un agent de police judiciaire ou un agent de la force publique, qui en fait exhibition à la personne et lui en délivre copie (','{}'::jsonb,true),
